// ============ FIRESTORE (con localStorage como cache) ============
function withTimeout(promise, ms) {
    return Promise.race([
        promise,
        new Promise((_, reject) => setTimeout(() => reject(new Error('timeout_firestore')), ms || 10000))
    ]);
}

function loadFichas() {
    return withTimeout(db_firestore.collection('fichas').get(), 10000).then(snapshot => {
        const fichas = [];
        snapshot.forEach(doc => fichas.push({ id: doc.id, ...doc.data() }));
        localStorage.setItem(STORAGE_KEY, JSON.stringify(fichas));
        return fichas;
    }).catch(() => {
        try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; } catch { return []; }
    });
}

function saveFichas(fichas) {
    return withTimeout(db_firestore.collection('fichas').get(), 10000).then(snapshot => {
        const batch = db_firestore.batch();
        const existingIds = new Set();
        snapshot.forEach(doc => existingIds.add(doc.id));
        fichas.forEach(f => {
            const ref = db_firestore.collection('fichas').doc(f.id);
            batch.set(ref, f);
            existingIds.delete(f.id);
        });
        existingIds.forEach(id => {
            const ref = db_firestore.collection('fichas').doc(id);
            batch.delete(ref);
        });
        return batch.commit();
    }).catch(e => {
        console.warn('Error guardando en Firestore:', e);
    }).then(() => {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(fichas));
    });
}

function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

function getNextRegistroNum() {
    return loadFichas().then(fichas => {
        fichas = fichasVivas(fichas);
        let maxNum = 0;
        fichas.forEach(f => {
            const num = parseInt(f.registroNum, 10);
            if (!isNaN(num) && num > maxNum) maxNum = num;
        });
        return maxNum + 1;
    });
}

function getNextCodigoSeguimiento() {
    const year = new Date().getFullYear();
    return loadFichas().then(fichas => {
        fichas = fichasVivas(fichas);
        let maxNum = 0;
        fichas.forEach(f => {
            const codigo = f.codigoSeguimiento || '';
            const m = /^(\d+)-SDC-(\d+)$/.exec(codigo);
            if (m && parseInt(m[2], 10) === year) {
                const n = parseInt(m[1], 10);
                if (!isNaN(n) && n > maxNum) maxNum = n;
            }
        });
        return String(maxNum + 1).padStart(2, '0') + '-SDC-' + year;
    });
}

