function skeletonFichas() {
    return '<div class="ficha-card skeleton-card" aria-hidden="true">' +
        '<div class="semaforo-post"><span></span><span></span><span></span></div>' +
        '<div class="ficha-card-content">' +
            '<div class="skeleton-line skeleton-w60"></div>' +
            '<div class="skeleton-line skeleton-w30"></div>' +
        '</div>' +
    '</div>'.repeat(3);
}

function renderFichasList() {
    fichasList.innerHTML = skeletonFichas();
    loadFichas().then(fichas => {
        fichasList.innerHTML = '';
        fichas = fichasVivas(fichas);

        let filtered = fichas;
        if (currentFilter === 'hoy') {
            filtered = filtered.filter(f => esDeHoy(f.fechaCreacion));
        } else if (currentFilter !== 'all') {
            filtered = filtered.filter(f => f.semaforo === currentFilter);
        }
        if (currentSearch) {
            const q = currentSearch.toLowerCase();
            filtered = filtered.filter(f =>
                (f.sector || '').toLowerCase().includes(q) ||
                (f.calle || '').toLowerCase().includes(q) ||
                (f.nombreAfectado || '').toLowerCase().includes(q) ||
                (f.tipoEmergencia || '').toLowerCase().includes(q) ||
                String(f.registroNum || '').includes(q)
            );
        }

        renderSidebarStats(fichas);
        actualizarPapeleraCount();

        if (filtered.length === 0) {
            fichasList.innerHTML = '<p class="empty-msg">' + (fichas.length === 0 ? 'No hay informes registrados' : 'No se encontraron resultados') + '</p>';
            return;
        }

        filtered.sort((a, b) => (b.fechaCreacion || 0) - (a.fechaCreacion || 0));

        filtered.forEach(f => {
            const card = document.createElement('div');
            card.className = 'ficha-card' + (currentViewId === f.id ? ' active' : '');
            card.dataset.id = f.id;

            const fecha = f.fechaVisita ? new Date(f.fechaVisita).toLocaleDateString('es-CL') : 'Sin fecha';
            const sector = f.sector || 'Sin sector';
            const estado = estadoControl(f);

            card.innerHTML =
                '<div class="semaforo-post" aria-hidden="true">' +
                    '<span class="verde"></span>' +
                    '<span class="amarillo"></span>' +
                    '<span class="rojo"></span>' +
                '</div>' +
                '<div class="ficha-card-content">' +
                    '<div class="ficha-card-header">' +
                        '<span class="ficha-card-dot ' + (f.semaforo || '') + '"></span>' +
                        '<span class="ficha-card-title">' + escapeHtml(sector) + '</span>' +
                        '<span class="estado-badge ' + estado + '">' + ESTADO_LABELS[estado] + '</span>' +
                    '</div>' +
                    '<div class="ficha-card-meta">' +
                        '<span class="ficha-card-reg">N&ordm; ' + (f.registroNum || '-') + '</span>' +
                        '<span>' + fecha + '</span>' +
                    '</div>' +
                '</div>';

            card.addEventListener('click', () => viewFicha(f.id));
            fichasList.appendChild(card);
        });
    });
}

function renderSidebarStats(fichas) {
    const counts = { verde: 0, amarillo: 0, rojo: 0 };
    fichas.forEach(f => { if (counts[f.semaforo] !== undefined) counts[f.semaforo]++; });

    sidebarStats.innerHTML =
        '<span class="stat-mini verde">' + counts.verde + ' Verde</span>' +
        '<span class="stat-mini amarillo">' + counts.amarillo + ' Amarillo</span>' +
        '<span class="stat-mini rojo">' + counts.rojo + ' Rojo</span>';
}

